17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.ArrayList;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
34	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.api.OwnersApi;
36	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
37	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.PetDto;
39	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.VisitDto;
41	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
42	import org.springframework.samples.petclinic.service.ClinicService;
43	import org.springframework.security.access.prepost.PreAuthorize;
44	import org.springframework.web.bind.annotation.CrossOrigin;
45	import org.springframework.web.bind.annotation.RequestMapping;
46	import org.springframework.web.bind.annotation.RestController;
47	import org.springframework.web.util.UriComponentsBuilder;
48	
49	import jakarta.transaction.Transactional;
50	
51	/**
52	 * @author Vitaliy Fedoriv
53	 */
54	
55	@RestController
56	@CrossOrigin(exposedHeaders = "errors, content-type")
57	@RequestMapping("/api")
58	public class OwnerRestControllerV1 implements OwnersApi {
59	
60	    private final ClinicService clinicService;
61	
62	    private final OwnerMapper ownerMapper;
63	
64	    private final PetMapper petMapper;
65	
66	    private final VisitMapper visitMapper;
67	
68	    public OwnerRestControllerV1(ClinicService clinicService,
69	                                 OwnerMapper ownerMapper,
70	                                 PetMapper petMapper,
71	                                 VisitMapper visitMapper) {
72	        this.clinicService = clinicService;
73	        this.ownerMapper = ownerMapper;
74	        this.petMapper = petMapper;
75	        this.visitMapper = visitMapper;
76	    }
77	
78	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
79	    @Override
80	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
81	        Collection<Owner> owners;
82	        if (lastName != null) {
83	            owners = this.clinicService.findOwnerByLastName(lastName);
84	        } else {
85	            owners = this.clinicService.findAllOwners();
86	        }
87	        if (owners.isEmpty()) {
88	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
89	        }
90	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
91	    }
92	
93	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
94	    @Override
95	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
96	        Owner owner = this.clinicService.findOwnerById(ownerId);
97	        if (owner == null) {
98	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
99	        }
100	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
101	    }
102	
103	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
104	    @Override
105	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
106	        rejectBlankOwnerFields(ownerFieldsDto);
107	        normalizeTelephone(ownerFieldsDto);
108	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
109	        HttpHeaders headers = new HttpHeaders();
110	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
111	        this.clinicService.saveOwner(owner);
112	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
113	        headers.setLocation(UriComponentsBuilder.newInstance()
114	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
115	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
116	    }
117	
118	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
119	    @Override
120	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
121	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
122	        if (currentOwner == null) {
123	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
124	        }
125	        currentOwner.setAddress(ownerFieldsDto.getAddress());
126	        currentOwner.setCity(ownerFieldsDto.getCity());
127	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
128	        currentOwner.setLastName(ownerFieldsDto.getLastName());
129	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
130	        this.clinicService.saveOwner(currentOwner);
131	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Transactional
136	    @Override
137	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
138	        Owner owner = this.clinicService.findOwnerById(ownerId);
139	        if (owner == null) {
140	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
141	        }
142	        this.clinicService.deleteOwner(owner);
143	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
144	    }
145	
146	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
147	    @Override
148	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
149	        Owner owner = this.clinicService.findOwnerById(ownerId);
150	        if (owner == null) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        HttpHeaders headers = new HttpHeaders();
154	        Pet pet = petMapper.toPet(petFieldsDto);
155	        owner.setId(ownerId);
156	        pet.setOwner(owner);
157	        pet.getType().setName(null);
158	        this.clinicService.savePet(pet);
159	        PetDto petDto = petMapper.toPetDto(pet);
160	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
161	            .buildAndExpand(pet.getId()).toUri());
162	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
163	    }
164	
165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
168	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
169	        if (currentOwner != null) {
170	            Pet currentPet = this.clinicService.findPetById(petId);
171	            if (currentPet != null) {
172	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
173	                currentPet.setName(petFieldsDto.getName());
174	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
175	                this.clinicService.savePet(currentPet);
176	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
177	            }
178	        }
179	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
185	        HttpHeaders headers = new HttpHeaders();
186	        Visit visit = visitMapper.toVisit(visitFieldsDto);
187	        Pet pet = new Pet();
188	        pet.setId(petId);
189	        visit.setPet(pet);
190	        this.clinicService.saveVisit(visit);
191	        VisitDto visitDto = visitMapper.toVisitDto(visit);
192	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
193	            .buildAndExpand(visit.getId()).toUri());
194	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
195	    }
196	
197	
198	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
199	    @Override
200	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
201	        Owner owner = this.clinicService.findOwnerById(ownerId);
202	        if (owner != null) {
203	            Pet pet = owner.getPet(petId);
204	            if (pet != null) {
205	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
206	            }
207	        }
208	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
209	    }
210	
211	    /**
212	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
213	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
214	     * the request body already rejects null and empty values, but permits whitespace-only strings
215	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
216	     * that gap so every required field must carry a non-blank value.
217	     *
218	     * @param ownerFieldsDto the submitted owner fields
219	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
220	     */
221	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
222	        List<String> missing = new ArrayList<>();
223	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
224	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
225	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
226	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
227	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
228	        if (!missing.isEmpty()) {
229	            throw new InvalidOwnerFieldsException(missing);
230	        }
231	    }
232	
233	    private void addIfBlank(List<String> missing, String fieldName, String value) {
234	        if (value == null || value.isBlank()) {
235	            missing.add(fieldName);
236	        }
237	    }
238	
239	    /**
240	     * Normalizes the submitted {@code telephone} on create by removing every non-digit character,
241	     * then requires exactly 10 digits to remain. The stripped 10-digit value is written back onto
242	     * the request so it is the value stored and returned. Any input that does not reduce to exactly
243	     * 10 digits is rejected with a {@code 400 Bad Request}.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
246	     *                       {@link #rejectBlankOwnerFields} having already run)
247	     * @throws InvalidOwnerFieldsException if the telephone is not exactly 10 digits after stripping
248	     */
249	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
250	        String digits = ownerFieldsDto.getTelephone().replaceAll("\\D", "");
251	        if (digits.length() != 10) {
252	            throw new InvalidOwnerFieldsException(List.of("telephone"));
253	        }
254	        ownerFieldsDto.setTelephone(digits);
255	    }
256	
257	    /**
258	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
259	     * Every existing owner's stored telephone is normalized the same way (all non-digit characters
260	     * stripped) before comparison, so equality is judged on digits alone. A match is reported as a
261	     * {@code 409 Conflict}.
262	     *
263	     * @param normalizedTelephone the submitted telephone, already reduced to its 10 digits by
264	     *                            {@link #normalizeTelephone}
265	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
266	     */
267	    private void rejectDuplicateTelephone(String normalizedTelephone) {
268	        boolean inUse = this.clinicService.findAllOwners().stream()
269	            .map(Owner::getTelephone)
270	            .filter(Objects::nonNull)
